scroll-reveal.css:
.stack{padding:14vh 20px}
.row{max-width:820px;margin:0 auto 22vh}
.rev{background:#1c1c21;border:1px solid #33333c;border-radius:10px;padding:26px;
  animation:rv auto linear both;animation-timeline:view();
  animation-range:entry 10% cover 38%}
@keyframes rv{from{opacity:0;transform:translateY(28px)}to{opacity:1;transform:none}}
.rev h3{margin:0 0 8px;font-size:19px}
.rev p{margin:0;color:#a9a9b2}
.slow{animation-range:entry 0% cover 100%}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px}

scroll-reveal.snippet:
@keyframes reveal{
  from{ opacity:0; transform:translateY(28px) }
  to  { opacity:1; transform:translateY(0) }
}
.reveal > *{
  animation: reveal auto linear both;
  animation-timeline: view();
  animation-range: entry 10% cover 38%;   /* done well before centre screen */
}
@supports not (animation-timeline: view()){
  .reveal > *{ opacity:1; transform:none; animation:none }
}

scroll-progress.css:
.progress{position:fixed;inset:0 0 auto 0;height:6px;background:#e2231a;z-index:90;
  transform-origin:0 50%;
  animation:prg auto linear both;animation-timeline:scroll(root block)}
@keyframes prg{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.reading{max-width:70ch;margin:0 auto;padding:12vh 20px}
.reading p{margin:0 0 20px;color:#c3c3cb;font-size:16px;line-height:1.7}
.reading h3{margin:34px 0 12px;font-size:20px}
.ring{position:fixed;right:18px;bottom:18px;width:48px;height:48px;z-index:90}
.ring circle{fill:none;stroke-width:4}
.ring .t{stroke:#33333c}
.ring .p{stroke:#e2231a;stroke-dasharray:1;stroke-dashoffset:1;
  animation:ring auto linear both;animation-timeline:scroll(root block);
  transform:rotate(-90deg);transform-origin:50% 50%}
@keyframes ring{to{stroke-dashoffset:0}}

scroll-progress.reducedMotion:
/* NOT collapsed. WCAG 2.3.3 exempts motion that conveys position, and a
   reading-progress indicator is exactly that. engine.md §6 states the exception
   explicitly: decoration collapses, a progress bar stays. */

scroll-progress.snippet:
.progress{
  position: fixed; inset: 0 0 auto 0; height: 6px;
  transform-origin: 0 50%;
  animation: prg auto linear both;
  animation-timeline: scroll(root block);
}
@keyframes prg{ from{ transform:scaleX(0) } to{ transform:scaleX(1) } }

@supports not (animation-timeline: scroll()){ .progress{ display:none } }

parallax.css:
.bg{position:fixed;inset:-14% 0;z-index:-1;
  background:
    radial-gradient(58% 52% at 20% 24%,#7b2ff7 0%,transparent 62%),
    radial-gradient(54% 48% at 82% 32%,#f107a3 0%,transparent 60%),
    radial-gradient(68% 58% at 50% 90%,#ff6a3d 0%,transparent 65%),
    linear-gradient(160deg,#2b0b57,#4a0a3d 60%,#5c1f10)}
.plx{animation:px auto linear both;animation-timeline:scroll(root block)}
@keyframes px{from{transform:translateY(-8%) scale(1.16)}to{transform:translateY(8%) scale(1.16)}}
.sheet{max-width:64ch;margin:0 auto;padding:18vh 20px}
.card{background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.3);border-radius:16px;
  backdrop-filter:blur(16px) saturate(140%);-webkit-backdrop-filter:blur(16px) saturate(140%);
  padding:24px;margin-bottom:22vh;color:#fff}
.card h3{margin:0 0 8px;font-size:20px}
.card p{margin:0;font-size:16px}

parallax.snippet:
.bg{ position:fixed; inset:-14% 0; z-index:-1 }
.plx{
  animation: px auto linear both;
  animation-timeline: scroll(root block);   /* NOT view() — a fixed layer never enters */
}
@keyframes px{
  from{ transform: translateY(-8%) scale(1.16) }
  to  { transform: translateY( 8%) scale(1.16) }
}
@supports not (animation-timeline: scroll()){ .plx{ transform:none; animation:none } }

pinned-scene.css:
.stagewrap{height:300vh;position:relative}
.pinstage{position:sticky;top:0;height:100vh;overflow:hidden;
  display:grid;place-items:center;
  background:radial-gradient(70% 60% at 50% 40%,#243049,#0f1220 70%)}
.orbit{position:relative;width:min(420px,72vw);aspect-ratio:1}
.ring{position:absolute;inset:0;border:1px solid rgba(138,180,255,.34);border-radius:50%}
.ring.r2{inset:14%}.ring.r3{inset:28%}
.core{position:absolute;inset:38%;border-radius:50%;background:#8ab4ff;
  box-shadow:0 0 60px rgba(138,180,255,.5)}
.tick{position:absolute;left:50%;top:-6px;width:2px;height:14px;background:#8ab4ff;
  transform-origin:50% calc(50vw);}
.pinlabel{position:absolute;left:20px;bottom:20px;
  font:600 11px/1 ui-monospace,monospace;letter-spacing:.14em;text-transform:uppercase;color:#8ab4ff}
.passing{position:relative;z-index:3;max-width:56ch;margin:0 auto;padding:0 20px}
.passing section{min-height:100vh;display:flex;align-items:center}
.passing .plate{background:rgba(8,10,18,.86);border:1px solid #2a3450;border-radius:12px;padding:26px}
.passing h3{margin:0 0 10px;font-size:20px}
.passing p{margin:0;color:#c3c3cb;font-size:16px;line-height:1.7}
.stuckbar{position:sticky;top:0;z-index:70;background:#1c1c21;border-bottom:1px solid #33333c;
  padding:12px 16px;font:600 12px/1 ui-monospace,monospace;letter-spacing:.08em;
  container-type:scroll-state}
@supports (container-type: scroll-state){
  .stuckbar > span{transition:color .2s}
  @container scroll-state(stuck: top){ .stuckbar > span{color:#7ee787} }
}

pinned-scene.fallback:
@supports not (animation-timeline: view()){
  /* nothing to restore: this technique is position:sticky, which needs no
     timeline. The block is here so the rule is explicit rather than absent. */
  .pin{position:sticky}
}

pinned-scene.reducedMotion:
@media (prefers-reduced-motion: reduce){
  /* sticky is not motion — the element does not move, the page does. Nothing to
     collapse. Any SCRUBBED animation inside a pinned scene would collapse here. */
  .pin{position:sticky}
}

pinned-scene.snippet:
.track{ /* the containing block — must be taller than the pin */ }
.pin{ position: sticky; top: 14vh }

/* "has it stuck yet?" — in CSS, no listener. Chrome 133+ */
.bar{ container-type: scroll-state; position: sticky; top: 0 }
@supports (container-type: scroll-state){
  @container scroll-state(stuck: top){
    .bar{ box-shadow: 0 4px 0 0 currentColor }
  }
}

stacking-cards.css:
.stackwrap{max-width:900px;margin:0 auto;padding:8vh 20px 40vh}
.panel{position:sticky;top:calc(12vh + var(--i) * 18px);
  border:2px solid #000;border-radius:5px;box-shadow:8px 8px 0 0 #000;
  padding:34px;margin-bottom:26px}
.p0{background:#fff;color:#000}
.p1{background:#5b8def;color:#000}
.p2{background:#fff;color:#000}
.p3{background:#ff5252;color:#000}
.panel .idx{font:700 42px/1 ui-monospace,monospace;letter-spacing:-.04em;display:block;margin-bottom:8px}
.panel h3{margin:0 0 10px;font-size:24px;text-transform:uppercase;letter-spacing:-.02em}
.panel p{margin:0;max-width:52ch}

stacking-cards.fallback:
@supports not (animation-timeline: view()){
  /* no timeline is used: this is sticky plus an offset. Declared so the rule is
     explicit rather than assumed. */
  .panel{position:sticky}
}

stacking-cards.reducedMotion:
@media (prefers-reduced-motion: reduce){
  /* the panels do not move — the page does. Nothing to collapse. A scale or fade
     added on top of this WOULD collapse here, which is why the no-shrink variant
     is the one this pack uses. */
  .panel{position:sticky}
}

stacking-cards.snippet:
.panel{
  position: sticky;
  top: calc(12vh + var(--i) * 18px);   /* one property, any number of panels */
}
/* <article class="panel" style="--i:0"> … --i:1, --i:2 */

/* the wrapper needs trailing space or the last panel unsticks immediately */
.stackwrap{ padding-bottom: 40vh }

scroll-snap.css:
.snap{scroll-snap-type:y mandatory;overflow-y:auto;height:80vh;
  scroll-behavior:auto}
.snap > section{scroll-snap-align:start;scroll-snap-stop:always;
  min-height:80vh;display:grid;place-items:center;padding:40px 20px;
  container-type:scroll-state}
.s0{background:#0a49c4;color:#fff}.s1{background:#e01b24;color:#fff}
.s2{background:#f5c518;color:#111}.s3{background:#141417;color:#e7e7ea}
.snap h3{margin:0 0 12px;font-size:clamp(1.6rem,4vw,2.6rem);text-transform:uppercase;letter-spacing:-.02em}
.snap p{margin:0;max-width:52ch;font-size:16px}
.inner{text-align:center;transition:opacity .25s}
@supports (container-type: scroll-state){
  .snap > section .inner{opacity:.35}
  @container scroll-state(snapped: y){ .inner{opacity:1} }
}

scroll-snap.fallback:
@supports not (animation-timeline: view()){
  /* no timeline is used — snap is native. Declared so the rule is explicit. */
  .snap{scroll-snap-type:y mandatory}
}
@supports not (container-type: scroll-state){
  /* without scroll-state the dimming cannot be expressed, so nothing dims.
     The snap itself is unaffected. */
  .snap > section .inner{opacity:1}
}

scroll-snap.reducedMotion:
@media (prefers-reduced-motion: reduce){
  /* snap position is not motion; the browser jumps rather than animates when
     scroll-behavior is auto. The dimming transition collapses. */
  .inner{transition:none}
}

scroll-snap.snippet:
.snap{ scroll-snap-type: y mandatory; overflow-y: auto; height: 100vh }
.snap > section{
  scroll-snap-align: start;
  scroll-snap-stop: always;          /* a fast flick cannot skip a panel */
  container-type: scroll-state;      /* so a child can ask if it is snapped */
}
@supports (container-type: scroll-state){
  .snap > section .inner{ opacity:.35 }
  @container scroll-state(snapped: y){ .inner{ opacity:1 } }
}

horizontal-scroll.css:
.hwrap{padding:10vh 0}
.hscroll{display:flex;gap:16px;overflow-x:auto;scroll-snap-type:x mandatory;
  padding:0 20px 18px;container-type:scroll-state}
.hscroll > figure{flex:0 0 min(74%,420px);scroll-snap-align:start;margin:0;
  border:1px solid #33333c;border-radius:12px;overflow:hidden;background:#1c1c21;
  container-type:scroll-state}
.hscroll .art{aspect-ratio:4/3;display:grid;place-items:center;
  font:700 13px/1 ui-monospace,monospace;letter-spacing:.14em;color:#0f0f11}
.a0{background:#0a49c4;color:#fff}.a1{background:#e01b24;color:#fff}
.a2{background:#f5c518}.a3{background:#25d366}.a4{background:#8ab4ff}
.hscroll figcaption{padding:16px;color:#c3c3cb;font-size:15px}
.hint{max-width:78ch;margin:0 auto;padding:0 20px 6px;color:#8b8b95;
  font:500 12px/1.6 ui-monospace,monospace}
@supports (container-type: scroll-state){
  .edgehint{opacity:0;transition:opacity .2s}
  @container scroll-state(scrollable: right){ .edgehint{opacity:1} }
}

horizontal-scroll.fallback:
@supports not (animation-timeline: view()){
  /* native overflow — no timeline involved. Declared so the rule is explicit. */
  .hscroll{overflow-x:auto}
}
@supports not (container-type: scroll-state){
  /* without scroll-state the affordance cannot be conditional, so show it always.
     Better a permanent hint than a hidden one. */
  .edgehint{opacity:1}
}

horizontal-scroll.snippet:
.hscroll{
  display: flex; gap: 16px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  container-type: scroll-state;      /* so the hint can ask if more remains */
}
.hscroll > *{ flex: 0 0 min(74%, 420px); scroll-snap-align: start }

@supports (container-type: scroll-state){
  @container scroll-state(scrollable: right){ .edgehint{ opacity:1 } }
}

scrollytelling.css:
.story{max-width:1100px;margin:0 auto;padding:0 20px;
  display:grid;grid-template-columns:1fr 1fr;gap:52px;align-items:start}
@media(max-width:860px){.story{grid-template-columns:1fr}}
.viz{position:sticky;top:12vh;aspect-ratio:1;border-radius:12px;border:1px solid #33333c;
  background:#17171b;display:grid;place-items:center;overflow:hidden}
.fig{position:absolute;inset:0;display:grid;place-items:center;opacity:0;
  animation:step auto linear both;animation-timeline:view();
  animation-range:cover 0% cover 100%;font:700 14px/1 ui-monospace,monospace;
  letter-spacing:.16em;color:#0f0f11}
@keyframes step{0%{opacity:0}18%{opacity:1}82%{opacity:1}100%{opacity:0}}
.f0{background:#0a49c4;color:#fff}.f1{background:#e01b24;color:#fff}
.f2{background:#f5c518}.f3{background:#25d366}
.steps > section{min-height:78vh;display:flex;flex-direction:column;justify-content:center}
.steps h3{margin:0 0 12px;font-size:21px}
.steps p{margin:0 0 16px;color:#c3c3cb;font-size:16px;line-height:1.7;max-width:52ch}

scrollytelling.fallback:
@supports not (animation-timeline: view()){
  /* every step would stay at opacity:0 and the visual would be blank. Show the
     first and hide the rest — a static illustration is a valid degraded state. */
  .fig{opacity:0;animation:none}
  .fig.f0{opacity:1}
}

scrollytelling.snippet:
.viz{ position: sticky; top: 12vh }        /* the visual holds */
.fig{
  position: absolute; inset: 0; opacity: 0;
  animation: step auto linear both;
  animation-timeline: view();             /* each step, its own progress */
  animation-range: cover 0% cover 100%;
}
@keyframes step{ 0%{opacity:0} 18%{opacity:1} 82%{opacity:1} 100%{opacity:0} }

@supports not (animation-timeline: view()){
  .fig{ opacity:0; animation:none } .fig.f0{ opacity:1 }   /* show something */
}

text-reveal.css:
.trwrap{max-width:900px;margin:0 auto;padding:26vh 20px}
.tr{font:700 clamp(1.8rem,5vw,3.4rem)/1.15 ui-sans-serif,system-ui;letter-spacing:-.02em;
  margin:0 0 30vh}
.tr span{opacity:.16;
  animation:word auto linear both;animation-timeline:view();
  animation-range:entry 24% cover 62%}
@keyframes word{to{opacity:1}}
.body{max-width:62ch;color:#c3c3cb;font-size:16px;line-height:1.7}
.body p{margin:0 0 18px}

text-reveal.snippet:
.tr span{
  opacity: .16;                     /* never 0 — the shape stays legible */
  animation: word auto linear both;
  animation-timeline: view();
  animation-range: entry 24% cover 62%;
}
@keyframes word{ to{ opacity:1 } }

@supports not (animation-timeline: view()){ .tr span{ opacity:1; animation:none } }

svg-path-draw.css:
.drawwrap{max-width:820px;margin:0 auto;padding:18vh 20px}
.card{margin-bottom:26vh;text-align:center}
.draw{width:100%;max-width:520px}
.draw path{fill:none;stroke:#7ee787;stroke-width:3;stroke-linecap:round;
  stroke-dasharray:1;stroke-dashoffset:1;
  animation:dw auto linear both;animation-timeline:view();
  animation-range:entry 5% cover 55%}
@keyframes dw{to{stroke-dashoffset:0}}
.draw.red path{stroke:#ff9492}
.draw.blue path{stroke:#8ab4ff}
.card h3{margin:16px 0 6px;font-size:19px}
.card p{margin:0 auto;max-width:52ch;color:#a9a9b2}

scroll-theme-shift.css:
.shift{min-height:96vh;display:grid;place-items:center;padding:8vh 20px;
  animation:th auto linear both;animation-timeline:view();
  animation-range:cover 10% cover 78%}
.t1{background:#ecf0f1;--from:#ecf0f1}
@keyframes th{from{background-color:#2c3e50}to{background-color:#20628f}}
.shift .in{max-width:56ch;text-align:center;color:#fff}
.shift h3{margin:0 0 12px;font-size:clamp(1.6rem,4vw,2.4rem)}
.shift p{margin:0;font-size:16px;line-height:1.7}
.pad{height:40vh}

scroll-theme-shift.fallback:
@supports not (animation-timeline: view()){
  /* without the timeline the element has no background at all, and white text
     would sit on the page ground. Pin it to the FROM colour. */
  .shift{background-color:#2c3e50;animation:none}
}

scroll-theme-shift.snippet:
.shift{
  background-color: #2c3e50;         /* the FROM colour, declared for real */
  animation: th auto linear both;
  animation-timeline: view();
  animation-range: cover 10% cover 78%;
}
@keyframes th{ from{ background-color:#2c3e50 } to{ background-color:#20628f } }

@supports not (animation-timeline: view()){
  .shift{ background-color:#2c3e50; animation:none }
}

scroll-marquee.css:
.mq{overflow:hidden;white-space:nowrap;border-block:3px solid #e7e7ea;
  padding:14px 0;margin:12vh 0;
  font:700 clamp(16px,2.4vw,28px)/1 ui-monospace,monospace;letter-spacing:.06em;
  text-transform:uppercase}
.mq .run{display:inline-block;
  animation:mq auto linear both;animation-timeline:scroll(root block)}
@keyframes mq{from{transform:translateX(0)}to{transform:translateX(-42%)}}
.mq.rev .run{animation-name:mqr}
@keyframes mqr{from{transform:translateX(-42%)}to{transform:translateX(0)}}
.mq .dot{color:#7ee787}
.copy{max-width:64ch;margin:0 auto;padding:0 20px;color:#c3c3cb;font-size:16px;line-height:1.7}
.copy p{margin:0 0 18px}
.pad{height:34vh}

scroll-marquee.snippet:
.mq{ overflow: hidden; white-space: nowrap }
.mq .run{
  display: inline-block;             /* transform needs a block box */
  animation: mq auto linear both;
  animation-timeline: scroll(root block);
}
@keyframes mq{ from{ transform:translateX(0) } to{ transform:translateX(-42%) } }

@supports not (animation-timeline: scroll()){ .run{ transform:none; animation:none } }

smooth-scroll.css:
.warn{max-width:70ch;margin:0 auto;padding:12vh 20px}
.warn h3{margin:26px 0 10px;font-size:20px}
.warn p{margin:0 0 16px;color:#c3c3cb;font-size:16px;line-height:1.7}
.flag{border-left:3px solid #ff9492;background:#241a1a;padding:16px 18px;border-radius:0 8px 8px 0;
  margin:0 0 20px}
.flag b{color:#ff9492}
.ok{border-left:3px solid #7ee787;background:#141f16;padding:16px 18px;border-radius:0 8px 8px 0;
  margin:0 0 20px}
.ok b{color:#7ee787}
.demo-note{background:#1c1c21;border:1px solid #33333c;border-radius:10px;padding:20px;
  margin:0 0 22px}
.compare{width:100%;border-collapse:collapse;font-size:14px;margin:8px 0 20px}
.compare th,.compare td{text-align:left;padding:9px 10px;border-bottom:1px solid #33333c;
  vertical-align:top}
.compare th{color:#8b8b95;font:600 11px/1 ui-monospace,monospace;letter-spacing:.08em;
  text-transform:uppercase}

smooth-scroll.fallback:
@supports not (animation-timeline: scroll()){
  /* nothing to fall back FROM: this section deliberately ships no smooth scroll.
     The rule is declared so the absence is a decision rather than an oversight. */
  .warn{scroll-behavior:auto}
}

smooth-scroll.reducedMotion:
@media (prefers-reduced-motion: reduce){
  /* If you do ship smooth scroll, this is not optional — a lerped scroll is
     exactly the vestibular trigger WCAG 2.3.3 is about. Disable the library. */
  html{scroll-behavior:auto}
}

smooth-scroll.snippet:
/* CSS gives you the safe part for free — anchor jumps only, and it
   already honours the user's motion preference. */
html{ scroll-behavior: smooth }
@media (prefers-reduced-motion: reduce){ html{ scroll-behavior: auto } }

/* What you probably wanted instead — smooth the ANIMATION, not the scroll: */
// anime.js:  autoplay: onScroll({ sync: 0.25 })
// GSAP:      scrollTrigger: { scrub: 1 }

video-scrub.css:
.scrubwrap{--n:48;--slice:calc(100% / var(--n));
  height:340vh;position:relative;
  /* The timeline must come from the TALL WRAPPER, not from the frames. The
     frames live inside a sticky stage that never traverses the viewport, so
     their own view() progress never advances — the same failure as putting
     view() on a fixed parallax layer. A named timeline on the wrapper is
     found by descendants through the ancestor chain. */
  view-timeline-name:--scrub;view-timeline-axis:block}
.sticky{position:sticky;top:0;height:100vh;display:grid;place-items:center;overflow:hidden}
.stage{position:relative;width:min(960px,92vw);aspect-ratio:16/9;
  border:1px solid #33333c;border-radius:10px;overflow:hidden;background:#121216}
.fr{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;
  animation:show auto steps(1,end) both;
  animation-timeline:--scrub;
  animation-range:contain calc(var(--i) * var(--slice)) contain calc((var(--i) + 0.001) * var(--slice))}
@keyframes show{to{opacity:1}}
.fr:first-child{opacity:1}
.cap{position:absolute;left:14px;bottom:12px;z-index:5;
  font:600 11px/1 ui-monospace,monospace;letter-spacing:.1em;text-transform:uppercase;
  color:#0f0f11;background:#7ee787;padding:6px 9px;border-radius:3px}
.lead{max-width:70ch;margin:0 auto;padding:14vh 20px 6vh;color:#c3c3cb;font-size:16px;line-height:1.7}
.lead p{margin:0 0 16px}
.nums{width:100%;border-collapse:collapse;font-size:14px;margin:6px 0 18px}
.nums th,.nums td{text-align:left;padding:9px 10px;border-bottom:1px solid #33333c}
.nums th{color:#8b8b95;font:600 11px/1 ui-monospace,monospace;letter-spacing:.08em;text-transform:uppercase}

video-scrub.fallback:
@supports not (animation-timeline: view()){
  /* every frame would stay at opacity:0 and the stage would be empty. Show the
     first frame — a poster is a valid degraded state; a blank box is not. */
  .fr{opacity:0;animation:none}
  .fr:first-child{opacity:1}
}

video-scrub.reducedMotion:
@media (prefers-reduced-motion: reduce){
  /* a scrubbed sequence is continuous motion bound to input. Collapse to a
     single poster frame and never scrub. */
  .fr{animation:none;opacity:0}
  .fr:first-child{opacity:1}
}

video-scrub.snippet:
.wrap{                                /* the TALL element owns the timeline */
  --n:48; --slice: calc(100% / var(--n));
  height: 340vh;
  view-timeline-name: --scrub;
  view-timeline-axis: block;
}

.fr{                                  /* every frame, stacked */
  position:absolute; inset:0; opacity:0;
  animation: show auto steps(1,end) both;
  animation-timeline: --scrub;        /* NOT view() — the frames never move */
  animation-range:
    contain calc(var(--i) * var(--slice))
    contain calc((var(--i) + 0.001) * var(--slice));
}
@keyframes show{ to{ opacity:1 } }

<!-- <img class="fr" style="--i:0"> … --i:47 -->

@supports not (animation-timeline: view()){
  .fr{ opacity:0 } .fr:first-child{ opacity:1 }   /* poster, never a blank box */
}

scroll-world.css:
.worldwrap{--n:40;--slice:calc(100% / var(--n));height:320vh;position:relative;
  view-timeline-name:--world;view-timeline-axis:block}
