view-transition.css:
.vtwrap{max-width:960px;margin:0 auto;padding:10vh 20px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px;margin:0 0 26px}
.tile{aspect-ratio:1;border-radius:12px;display:grid;place-items:center;cursor:pointer;
  border:1px solid #33333c;font:700 12px/1 ui-monospace,monospace;letter-spacing:.1em;color:#0f0f11}
.c0{background:#8ab4ff}.c1{background:#7ee787}.c2{background:#e3b341}.c3{background:#ff9492}
.c4{background:#d2a8ff}.c5{background:#79c0ff}
.detail{display:none;border:1px solid #33333c;border-radius:14px;overflow:hidden;margin:0 0 26px}
.detail.on{display:block}
.detail .art{aspect-ratio:21/9;display:grid;place-items:center;
  font:700 15px/1 ui-monospace,monospace;letter-spacing:.14em;color:#0f0f11}
.detail .body{padding:22px;color:#c3c3cb;font-size:16px;line-height:1.7}
.controls{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 22px}
.btn{font:600 13px/1 ui-monospace,monospace;letter-spacing:.06em;text-transform:uppercase;
  background:#26262c;color:#e7e7ea;border:1px solid #3a3a44;border-radius:6px;
  padding:11px 16px;cursor:pointer}
.btn:hover{background:#33333c}
.btn:focus-visible{outline:2px solid #7ee787;outline-offset:2px}
.note{color:#8b8b95;font:500 13px/1.6 ui-monospace,monospace;margin:0 0 18px}
.lead{color:#c3c3cb;font-size:16px;line-height:1.7;margin:0 0 16px}

/* the tile and the detail art share a name, so the browser morphs between them */
::view-transition-old(card),::view-transition-new(card){animation-duration:.42s}
::view-transition-group(card){animation-timing-function:cubic-bezier(.2,.7,.2,1)}

view-transition.fallback:
@supports not (animation-timeline: view()){
  /* no timeline is involved here. And the API's own fallback is the best in this
     folder: where startViewTransition is unsupported the DOM simply updates
     instantly, which is the web working normally. */
  .detail{border-radius:14px}
}

view-transition.reducedMotion:
@media (prefers-reduced-motion: reduce){
  /* NOT automatic — a view transition is page-level motion under engine.md §6.
     Strip every name so the browser has nothing to animate between. */
  *{view-transition-name:none !important}
}

view-transition.snippet:
// same document
document.startViewTransition(() => { updateTheDOM() });

// give the two elements the same name and the browser morphs between them
tile.style.viewTransitionName = 'card';
detailArt.style.viewTransitionName = 'card';   // names must be UNIQUE per document

/* cross-document — no framework, no JS at all */
@view-transition { navigation: auto }

@media (prefers-reduced-motion: reduce){
  *{ view-transition-name: none !important }
}

view-transition.script:
(function(){
  var grid=document.getElementById('grid'), detail=document.getElementById('detail');
  var art=document.getElementById('art'), dtext=document.getElementById('dtext');
  var sup=document.getElementById('support');
  var supported = typeof document.startViewTransition === 'function';
  sup.textContent = supported
    ? 'document.startViewTransition() \u2014 supported in this browser'
    : 'startViewTransition() NOT supported here: the panel still opens, instantly. That is the fallback, and it is simply the web working normally.';
  var current = null;
  function reduce(){ return matchMedia('(prefers-reduced-motion: reduce)').matches }

  function apply(k){
    if(current !== null){
      var prev = grid.querySelector('[data-k="' + current + '"]');
      if(prev) prev.style.viewTransitionName = '';
    }
    art.className = 'art c' + k;
    art.textContent = 'DETAIL 0' + (Number(k) + 1);
    dtext.textContent = 'Tile 0' + (Number(k) + 1) + ' and this panel shared one view-transition-name, so the browser morphed the element rather than crossfading two pictures.';
    detail.classList.add('on');
    current = k;
    art.style.viewTransitionName = '';
  }
  function open(k){
    if(!supported || reduce()){ apply(k); return; }
    var tile = grid.querySelector('[data-k="' + k + '"]');
    if(tile) tile.style.viewTransitionName = 'card';
    art.style.viewTransitionName = 'card';
    document.startViewTransition(function(){ apply(k) });
  }
  grid.addEventListener('click', function(e){
    var b = e.target.closest('[data-k]');
    if(b) open(b.dataset.k);
  });
  document.getElementById('close').addEventListener('click', function(){
    var run = function(){ detail.classList.remove('on') };
    (supported && !reduce()) ? document.startViewTransition(run) : run();
  });
  document.getElementById('noVt').addEventListener('click', function(){
    apply(String(Math.floor(Math.random() * 6)));
  });
})();
